{
  "name": "sistema-agendamento",
  "version": "1.0.0",
  "description": "Sistema de agendamento de servicos",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "dependencies": {
    "express": "^4.18.2",
    "express-session": "^1.17.3",
    "bcryptjs": "^2.4.3",
    "better-sqlite3": "^9.4.3"
  },
